-- Table: masterdata_user
-- Source: accounting_admin_db.sql (1. Master data)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS masterdata_user (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username        VARCHAR(50)  NOT NULL UNIQUE,
    name            VARCHAR(150) NOT NULL,
    email           VARCHAR(255) NOT NULL UNIQUE,
    role            VARCHAR(30)  NOT NULL
                    CHECK (role IN ('SUPER_ADMIN', 'SALES_ADMIN', 'ACCOUNTING_ADMIN', 'OWNER')),
    password_hash   TEXT         NOT NULL,
    avatar          TEXT         NOT NULL DEFAULT '',
    status          VARCHAR(20)  NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'inactive', 'locked')),
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);
